+Triangle::Triangle(double a, double b, double c) : a_(a), b_(b), c_(c) {
+    if (a <= 0 || b <= 0 || c <= 0) {
+        throw std::invalid_argument("Side lengths must be positive");
+    }
+    if (a + b <= c || a + c <= b || b + c <= a) {
+        throw std::invalid_argument("The given sides do not form a valid triangle");
